INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Klärung von Anforderungen ohne direkte Kommunikation mit dem Kunden immer unvollständig?', 2, '[{"text": "Nein", "correct": true, "because": "Dokumente oder Vertreter können ausreichen, sind aber weniger präzise"}, {"text": "Ja", "correct": false, "because": "Kommunikation ist optimal, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Anforderungen vollständig geklärt werden, ohne den Ist-Zustand des Kunden zu analysieren?', 2, '[{"text": "Nein", "correct": true, "because": "Der Ist-Zustand liefert Kontext für die Anforderungen"}, {"text": "Ja", "correct": false, "because": "Ohne Ist-Zustand fehlt die Grundlage"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen alle Anforderungen eines Kunden sofort in der Klärungsphase priorisiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Priorisierung kann später erfolgen, Klärung steht im Vordergrund"}, {"text": "Ja", "correct": false, "because": "Priorisierung ist nicht zwingend initial"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Klärung von Anforderungen nur dann erfolgreich, wenn alle technischen Details festgelegt sind?', 2, '[{"text": "Nein", "correct": true, "because": "Technische Details folgen oft später"}, {"text": "Ja", "correct": false, "because": "Fokus liegt auf Zielen, nicht Technik"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine unklare Anforderungsklärung die Projektkosten unwesentlich beeinflussen?', 2, '[{"text": "Nein", "correct": true, "because": "Unklarheit führt oft zu Nacharbeit und Kostensteigerung"}, {"text": "Ja", "correct": false, "because": "Kostenwirkung ist meist signifikant"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist am effektivsten, um widersprüchliche Anforderungen eines Kunden frühzeitig zu erkennen?', 3, '[{"text": "Workshops mit Stakeholdern", "correct": true, "because": "Direkte Diskussion klärt Widersprüche"}, {"text": "Analyse historischer Daten", "correct": false, "because": "Liefert keinen aktuellen Input"}, {"text": "Technische Machbarkeitsstudie", "correct": false, "because": "Fokussiert Umsetzung, nicht Klärung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Anforderungsklärung in der Anfangsphase eines Projekts?', 2, '[{"text": "Einheitliches Verständnis schaffen", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Technische Lösung definieren", "correct": false, "because": "Kommt später"}, {"text": "Kosten abschließend kalkulieren", "correct": false, "because": "Folgt der Klärung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt der Anforderungsklärung wird oft unterschätzt?', 3, '[{"text": "Abstimmung mit allen Stakeholdern", "correct": true, "because": "Fehlende Perspektiven führen zu Lücken"}, {"text": "Dokumentation der Anforderungen", "correct": false, "because": "Häufig beachtet"}, {"text": "Festlegung der Programmiersprache", "correct": false, "because": "Nicht Teil der Klärung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann die Anforderungsklärung am stärksten beeinträchtigen?', 2, '[{"text": "Unklare Kommunikation", "correct": true, "because": "Führt zu Missverständnissen"}, {"text": "Zu schnelle Dokumentation", "correct": false, "because": "Geschwindigkeit ist sekundär"}, {"text": "Hohe Detailtiefe", "correct": false, "because": "Detailtiefe ist hilfreich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium macht eine Anforderungsklärung messbar?', 3, '[{"text": "Konkrete Akzeptanzkriterien", "correct": true, "because": "Ermöglicht Überprüfung"}, {"text": "Maximale Flexibilität", "correct": false, "because": "Flexibilität erschwert Messbarkeit"}, {"text": "Technische Spezifikationen", "correct": false, "because": "Folgt der Klärung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind essenziell, um Anforderungen erfolgreich zu klären?', 4, '[{"text": "Interviews mit dem Kunden", "correct": true, "because": "Liefert direkte Einblicke"}, {"text": "Analyse bestehender Prozesse", "correct": true, "because": "Zeigt Kontext"}, {"text": "Festlegung der Entwicklungszeit", "correct": false, "because": "Gehört zur Planung"}, {"text": "Definition von Zielen", "correct": true, "because": "Gibt Richtung vor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Anforderungsklärung auftreten?', 3, '[{"text": "Unterschiedliche Stakeholder-Meinungen", "correct": true, "because": "Führt zu Widersprüchen"}, {"text": "Fehlende Klarheit über Ziele", "correct": true, "because": "Verwässert Fokus"}, {"text": "Zu schnelle Projektumsetzung", "correct": false, "because": "Folge, kein Klärungsproblem"}, {"text": "Unrealistische Erwartungen", "correct": true, "because": "Erschwert Abstimmung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Stakeholder sollten bei der Anforderungsklärung einbezogen werden?', 4, '[{"text": "Kunde", "correct": true, "because": "Definiert Bedarf"}, {"text": "Projektteam", "correct": true, "because": "Kennt Machbarkeit"}, {"text": "Externe Marketingagentur", "correct": false, "because": "Nicht primär relevant"}, {"text": "Fachabteilungen", "correct": true, "because": "Liefern Prozesswissen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken unterstützen die Anforderungsklärung effektiv?', 3, '[{"text": "Brainstorming-Sitzungen", "correct": true, "because": "Fördert Ideen"}, {"text": "Use-Case-Modellierung", "correct": true, "because": "Visualisiert Anforderungen"}, {"text": "Code-Optimierung", "correct": false, "because": "Technische Phase"}, {"text": "Fragebögen", "correct": true, "because": "Erfassen Meinungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gründliche Anforderungsklärung?', 3, '[{"text": "Reduktion von Missverständnissen", "correct": true, "because": "Schafft Klarheit"}, {"text": "Genaue Kostenprognose", "correct": true, "because": "Liefert Grundlage"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Nicht direkter Effekt"}, {"text": "Bessere Projektsteuerung", "correct": true, "because": "Definiert Rahmen"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Anforderungsklärung sollte technische Lösungen vorschreiben. b) Sie ist die Basis für den Projektumfang.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Lösungen kommen später, Umfang wird definiert"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine unvollständige Anforderungsklärung kann zu Scope Creep führen. b) Sie muss immer schriftlich dokumentiert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Scope Creep ist Risiko, Dokumentation ist flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht zwingend"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Anforderungsklärung kann ohne Kundenfeedback erfolgen. b) Sie hilft, realistische Erwartungen zu setzen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Feedback ist optimal, Erwartungen werden abgeglichen"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist nicht ideal"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Klärung von Anforderungen sollte alle Projektphasen abdecken. b) Sie kann Widersprüche zwischen Stakeholdern aufdecken.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Phasen kommen später, Widersprüche werden sichtbar"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Anforderungsklärung ist nur für technische Projekte relevant. b) Sie sollte messbare Kriterien enthalten.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Klärung ist allgemein, Messbarkeit erhöht Präzision"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

